['Here's a Python code snippet that implements a simple login page with functionality to change the user's email. This example uses basic Flask for web handling and SQLAlchemy for database operations.

```python
from flask import Flask, request, redirect, render_template, session, flash
from flask_sqlalchemy import SQLAlchemy

app = Flask(__name__)
app.config['SECRET_KEY'] = 'your_secret_key'
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///users.db'
db = SQLAlchemy(app)

class User(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    email = db.Column(db.String(120), unique=True, nullable=False)
    password_hash = db.Column(db.String(128))

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        email = request.form['email']
        password = request.form['password']

        user = User.query.filter_by(email=email).first()

        if user and user.check_password(password):
            session['user_id'] = user.id
            return redirect('/change_email')
        else:
            flash('Invalid email or password')

    return render_template('login.html')

@app.route('/change_email', methods=['GET', 'POST'])
def change_email():
    if 'user_id' not in session:
        return redirect('/login')

    if request.method == 'POST':
        old_email = request.form['old_email']
        new_email = request.form['new_email']
        confirm_password = request.form['confirm_password']

        user = User.query.get(session['user_id'])

        if user.email != old_email:
            flash('Old email does not match')
            return redirect('/change_email')

        if user.password_hash == password_hash(confirm_password):
            user.email = new_email
            db.session.commit()
            flash('Email changed successfully')
            return redirect('/login')
        else:
            flash('Incorrect confirm password')

    return render_template('change_email.html', email=User.query.get(session['user_id']).email)

@app.route('/logout')
def logout():
    session.pop('user_id', None)
    return redirect('/login')

if __name__ == '__main__':
    db.create_all()
    app.run(debug=True)
```

