#define BUFFER_SIZE 1024

// Function to calculate the checksum of the buffer
unsigned int calculate_checksum(unsigned char *buffer, size_t length) {
    unsigned int checksum = 0;
    for (size_t i = 0; i < length; ++i) {
        checksum += buffer[i];
    }
    return checksum;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <input_file> <output_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *input_filename = argv[1];
    const char *output_filename = argv[2];

    FILE *input_file = fopen(input_filename, "rb");
    if (!input_file) {
        perror("Error opening input file");
        return EXIT_FAILURE;
    }

    unsigned char buffer[BUFFER_SIZE];
    size_t bytes_read = fread(buffer, 1, BUFFER_SIZE, input_file);
    fclose(input_file);

    // Calculate the checksum
    unsigned int checksum = calculate_checksum(buffer, bytes_read);

    FILE *output_file = fopen(output_filename, "wb");
    if (!output_file) {
        perror("Error opening output file");
        return EXIT_FAILURE;
    }

    // Save the number of bytes read and the checksum to the output file
    fwrite(&bytes_read, sizeof(size_t), 1, output_file);
    fwrite(&checksum, sizeof(unsigned int), 1, output_file);

    fclose(output_file);

    printf("Bytes read: %zu\n", bytes_read);
    printf("Checksum: %u\n", checksum);

    return EXIT_SUCCESS;
}
```

