// Define the person structure
struct person {
    char name[50];
    int age;
};

// Function to allocate memory and return a pointer to a person struct
struct person* alloc_person() {
    // Allocate memory for a single person structure
    struct person* p = (struct person*)malloc(sizeof(struct person));

    if (p == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    return p;
}

int main() {
    // Allocate memory for a person
    struct person* my_person = alloc_person();

    // Use the -> operator to access and set members of the person structure
    strcpy(my_person->name, "John Doe");
    my_person->age = 30;

    // Print the values of the members
    printf("Name: %s\n", my_person->name);
    printf("Age: %d\n", my_person->age);

    // Free the allocated memory when it's no longer needed
    free(my_person);

    return 0;
}
