#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

int main() {
    // Seed for random number generation
    srand(time(0));

    // Generate 3 random floats between 0 and 1
    float randFloat1 = (float)rand() / RAND_MAX;
    float randFloat2 = (float)rand() / RAND_MAX;
    float randFloat3 = (float)rand() / RAND_MAX;

    // Convert floats to strings
    char str1[50];
    char str2[50];
    char str3[50];

    snprintf(str1, sizeof(str1), "%f", randFloat1);
    snprintf(str2, sizeof(str2), "%f", randFloat2);
    snprintf(str3, sizeof(str3), "%f", randFloat3);

    // Concatenate the strings
    char result[200]; // Ensure this is large enough to hold all parts and null terminator
    snprintf(result, sizeof(result), "%s%s%s", str1, str2, str3);

    // Write the string to a file
    FILE *file = fopen("output.txt", "w");
    if (file == NULL) {
        perror("Error opening file");
        return 1;
    }

    fprintf(file, "%s", result);
    fclose(file);

    printf("Random floats and their concatenation have been written to 'output.txt'\n");

    return 0;
}
