        "    <title>Hello Page</title>\n"
        "</head>\n"
        "<body>\n"
        "    <h1>Hello, %s!</h1>\n"
        "    <p>Welcome to the Hello Page.</p>\n"
        "</body>\n"
        "</html>";

    // Write the response body to the response stream
    fprintf(response_stream, outputbuf, username);

    // Close the response stream
    fclose(response_stream);
}

int main() {
    // Example usage: Simulating a request and response
    FILE *request_stream = fopen("request.txt", "r");
    if (!request_stream) {
        perror("Failed to open request file");
        return EXIT_FAILURE;
