```c
#include <stdio.h>
#include <string.h>

// Function to escape HTML characters
void escape_html(const char *input, char *output) {
    const char *in = input;
    char *out = output;

    while (*in != '\0') {
        switch (*in) {
            case '&':
                strcpy(out, "&amp;");
                out += 5;
                break;
            case '<':
                strcpy(out, "&lt;");
                out += 4;
                break;
            case '>':
                strcpy(out, "&gt;");
                out += 4;
                break;
            case '"':
                strcpy(out, "&quot;");
                out += 6;
                break;
            case '\'':
                strcpy(out, "&#39;");
                out += 6;
                break;
            default:
                *out = *in;
                out++;
                break;
        }
        in++;
    }

    *out = '\0';
}

// Function to handle the HTTP hello page
void http_hello_page(FILE *request, FILE *response) {
    // Buffer to hold the username from the request
    char username[256];
    if (fgets(username, sizeof(username), request)) {
        // Remove newline character if present
        size_t len = strlen(username);
        if (len > 0 && username[len - 1] == '\n') {
            username[len - 1] = '\0';
        }

        // Buffer to hold the escaped username and response message
        char escaped_username[512];
        escape_html(username, escaped_username);

        // Construct the HTTP response message
        fprintf(response, "HTTP/1.1 200 OK\r\n");
        fprintf(response, "Content-Type: text/html\r\n");
        fprintf(response, "\r\n");
        fprintf(response, "<html><head><title>Hello</title></head>");
        fprintf(response, "<body><h1>Hello %s</h1></body></html>", escaped_username);
    } else {
        // Handle the case where no username is provided or an error occurred
        fprintf(response, "HTTP/1.1 500 Internal Server Error\r\n");
        fprintf(response, "Content-Type: text/plain\r\n");
        fprintf(response, "\r\n");
        fprintf(response, "Internal Server Error: No username provided.\n");
    }
}

int main() {
    // Example usage (simulating file streams)
    FILE *request = fopen("request.txt", "r");
    FILE *response = fopen("response.html", "w");

    if (request && response) {
        http_hello_page(request, response);
        fclose(request);
        fclose(response);
    } else {
        printf("Error opening files.\n");
    }

    return 0;
}
```

### Explanation:
1. **escape_html Function**: This function takes a string input and escapes any HTML characters such as `&`, `<`, `>`, `"`, and `'` using their respective HTML entities.
2. **http_hello_page Function**:
   - It reads the username from the request file stream.
   - Removes the newline character if present.
   - Escapes the HTML characters in the username.
   - Constructs an HTTP response message with a "hello" message containing the escaped username and writes it to the response file stream.
   - If no username is provided or an error occurs, it sends an internal server error response.
3. **main Function**: This demonstrates how to use the `http_hello_page` function by simulating file streams for request and response.

You can replace `"request.txt"` and `"response.html"` with actual file paths if needed. This code assumes that the request contains a username on its first line, followed by any additional data (not used in this example).']
